// Extract input parameters
const topic = $input.item.json.body?.topic || $input.item.json.topic || 'AI and technology';
const platform = $input.item.json.body?.platform || $input.item.json.platform || 'twitter';
const tone = $input.item.json.body?.tone || $input.item.json.tone || 'professional';
const includeHashtags = $input.item.json.body?.includeHashtags !== false;

// Platform-specific character limits and formatting
const platformConfig = {
  twitter: { maxLength: 280, name: 'Twitter/X' },
  linkedin: { maxLength: 3000, name: 'LinkedIn' },
  instagram: { maxLength: 2200, name: 'Instagram' },
  facebook: { maxLength: 5000, name: 'Facebook' },
  tiktok: { maxLength: 2200, name: 'TikTok' }
};

const config = platformConfig[platform.toLowerCase()] || platformConfig.twitter;

// Create prompt for AI
const prompt = `Generate a ${tone} social media post for ${config.name} about: ${topic}

Requirements:
- Maximum ${config.maxLength} characters
- Engaging and ${tone} tone
- Include a clear call-to-action
${includeHashtags ? '- Include 3-5 relevant hashtags at the end' : '- No hashtags'}
- Platform: ${config.name}
- Make it compelling and shareable

Format the response as JSON with:
- "content": the post text
- "hashtags": array of hashtags (if requested)
- "platform": the platform name
- "characterCount": character count of the content`;

return {
  json: {
    topic,
    platform,
    tone,
    includeHashtags,
    prompt,
    maxLength: config.maxLength,
    platformName: config.name
  }
};

// Parse AI response and format output
const aiResponse = $input.item.json.output || $input.item.json.text || '';
const originalInput = $('Prepare Prompt').item.json;

// Try to parse JSON from response
let content, hashtags, characterCount;

try {
  // Extract JSON if wrapped in markdown code blocks
  const jsonMatch = aiResponse.match(/```json\s*([\s\S]*?)\s*```/) || 
                    aiResponse.match(/```\s*([\s\S]*?)\s*```/) ||
                    aiResponse.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    content = parsed.content || parsed.text || aiResponse;
    hashtags = parsed.hashtags || [];
    characterCount = parsed.characterCount || content.length;
  } else {
    content = aiResponse.trim();
    hashtags = [];
    characterCount = content.length;
  }
} catch (e) {
  // If not JSON, use response as-is
  content = aiResponse.trim();
  hashtags = [];
  characterCount = content.length;
}

// Add hashtags if requested and not already included
if (originalInput.includeHashtags && hashtags.length > 0) {
  const hashtagString = hashtags.map(h => h.startsWith('#') ? h : '#' + h).join(' ');
  if (!content.includes(hashtagString)) {
    content = content + '\n\n' + hashtagString;
  }
}

// Ensure content doesn't exceed platform limit
if (content.length > originalInput.maxLength) {
  content = content.substring(0, originalInput.maxLength - 3) + '...';
}

return {
  json: {
    content: content.trim(),
    hashtags: hashtags,
    platform: originalInput.platformName,
    topic: originalInput.topic,
    tone: originalInput.tone,
    characterCount: content.length,
    maxLength: originalInput.maxLength,
    timestamp: new Date().toISOString(),
    readyToPost: content.length > 0 && content.length <= originalInput.maxLength
  }
};
